open SimpleGraph in
def IsCUTF {V : Type} (G : SimpleGraph V) : Prop :=
  ∃ H : ℕ → SimpleGraph V, (∀ i, (H i).CliqueFree 3) ∧ G = ⨆ i, H i

open SimpleGraph in
def IsProperEdgeColouring {V : Type} (G : SimpleGraph V) (c : Sym2 V → ℕ) : Prop :=
  ∀ a b d : V, G.Adj a b → G.Adj a d → b ≠ d → c s(a, b) ≠ c s(a, d)
